export const PRIME_SOURCE='https://www.federalreserve.gov/releases/h15/';
const clean=s=>s.replace(/<[^>]*>/g,' ').replace(/&nbsp;|&#160;/g,' ').replace(/\s+/g,' ').trim();
export function parsePrime(html,now=new Date()){
 const table=html.match(/<table\b[^>]*id=["']h15table["'][^>]*>([\s\S]*?)<\/table>/i)?.[1];
 if(!table)throw Error('Fed rate table not found');
 const dates=new Map();
 for(const m of table.matchAll(/<th\b([^>]*)>([\s\S]*?)<\/th>/gi)){
  const id=m[1].match(/\bid=["'](col\d+)["']/)?.[1];if(!id)continue;
  const text=clean(m[2]),parts=text.match(/^(\d{4})\s+([A-Za-z]+)\s+(\d{1,2})$/);if(!parts)continue;
  const month=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'].indexOf(parts[2].slice(0,3).toLowerCase());
  if(month<0)continue;
  const date=`${parts[1]}-${String(month+1).padStart(2,'0')}-${parts[3].padStart(2,'0')}`;
  const parsed=new Date(date+'T00:00:00Z');if(parsed.toISOString().slice(0,10)===date&&parsed<=now)dates.set(id,date);
 }
 const row=[...table.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].find(m=>/^Bank prime loan\b/i.test(clean(m[1].match(/<th\b[^>]*>([\s\S]*?)<\/th>/i)?.[1]||'')))?.[1];
 if(!row)throw Error('Bank prime loan row not found');
 const values=[];
 for(const m of row.matchAll(/<td\b([^>]*)>([\s\S]*?)<\/td>/gi)){
  const col=m[1].match(/\bcol\d+\b/)?.[0],date=dates.get(col),raw=clean(m[2]);
  if(!date||!/^\d+(\.\d+)?$/.test(raw))continue;
  const rate=Number(raw);if(rate>0&&rate<=30)values.push({rate,observationDate:date});
 }
 values.sort((a,b)=>b.observationDate.localeCompare(a.observationDate));
 if(!values.length)throw Error('No valid Prime observation');
 return {version:1,...values[0],source:PRIME_SOURCE,checkedAt:now.toISOString()};
}

export const MND_SOURCE='https://www.mortgagenewsdaily.com/mortgage-rates';
export function parseMnd(html,now=new Date()){
 const plain=s=>s.replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();
 for(const table of html.matchAll(/<table\b[^>]*>([\s\S]*?)<\/table>/gi)){
  let active=false,date=null;const rates={};
  for(const row of table[1].matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)){
   const s=row[1];
   if(/href=["']\/mortgage-rates\/(mnd|freddie-mac|mba)["']/i.test(s)){
    active=/href=["']\/mortgage-rates\/mnd["']/i.test(s);
    const m=plain(s).match(/(?:as of\s+)?(\d{1,2})\/(\d{1,2})\/(\d{2,4})/i);
    if(active&&m){const y=m[3].length===2?'20'+m[3]:m[3];date=`${y}-${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}`;}continue;
   }
   if(!active||!date)continue;
   const product=s.match(/href=["']\/mortgage-rates\/(30-year-fixed|15-year-fixed|30-year-fha|30-year-va)["']/)?.[1];
   const value=s.match(/<td\b[^>]*class=["']rate["'][^>]*>\s*(\d+(?:\.\d+)?)%\s*<\/td>/i)?.[1];
   if(product&&value){const rate=Number(value);if(rate>0&&rate<=30)rates[{'30-year-fixed':'fixed30','15-year-fixed':'fixed15','30-year-fha':'fha30','30-year-va':'va30'}[product]]={rate,observationDate:date};}
  }
  if(rates.fixed30&&rates.fixed15&&rates.fha30&&rates.va30){
   for(const entry of Object.values(rates)){const d=new Date(entry.observationDate+'T00:00:00Z');if(!Number.isFinite(+d)||d.toISOString().slice(0,10)!==entry.observationDate||d>now)throw Error('Invalid MND observation date');}
   return {version:1,rates,source:MND_SOURCE,checkedAt:now.toISOString()};
  }
 }
 throw Error('MND dated mortgage rate table not found');
}

export function createWorker(assets,seed,mndSeed=null){
 const states={prime:{value:seed,checked:0},mnd:{value:mndSeed,checked:0}};
 return {async fetch(request,env,ctx){
  const url=new URL(request.url);
  if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});
  if(url.pathname==='/api/prime'||url.pathname==='/api/mnd'){
   const kind=url.pathname.endsWith('/mnd')?'mnd':'prime',state=states[kind],source=kind==='mnd'?MND_SOURCE:PRIME_SOURCE,parse=kind==='mnd'?parseMnd:parsePrime;
   const observation=data=>kind==='mnd'?data?.rates.fixed30.observationDate:data?.observationDate;
   const key=new Request(url.origin+url.pathname);let cache;
   try{cache=globalThis.caches?.default;const cached=await cache?.match(key);if(cached)return cached;}catch{cache=undefined;}
   let data,fallback=false;
   try{
    if(Date.now()-state.checked<3600000)data=state.value;
    else{
     const r=await fetch(source,{signal:AbortSignal.timeout(10000),headers:{Accept:'text/html'}});
     if(!r.ok)throw Error('Rate source unavailable');
     data=parse(await r.text());
     if(state.value&&observation(data)<observation(state.value))throw Error('Observation older than saved value');
     state.value=data;state.checked=Date.now();
    }
   }catch{data=state.value;fallback=true;}
   if(!data)return Response.json({error:'Rate source unavailable'},{status:503});
   const response=Response.json({...data,fallback},{headers:{'Cache-Control':fallback?'public, max-age=60':'public, max-age=3600','X-Content-Type-Options':'nosniff'}});
   if(cache)try{await cache.put(key,response.clone());}catch{}
   return response;
  }
  const path=url.pathname==='/'?'/index.html':url.pathname,asset=assets[path];
  if(!asset)return new Response('Not found',{status:404});
  const bytes=Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0));
  return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}});
 }};
}

